mapper.update:
UPDATE gateway_wiki_revision SET deleted_at = (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{MP_OPTLOCK_VERSION_ORIGINAL}

UPDATE gateway_wiki_revision SET publication_status = 'SUPERSEDED',
    publication_version = publication_version + 1,
    version = version + 1,
    update_user_id = #{actorUserId}, update_time = #{now,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND kb_id = #{et.kbId} AND page_id = #{et.pageId}
    AND id <> #{newRevisionId}
    AND publication_status = 'PUBLISHED' AND publication_version = #{expectedPublicationVersion}
    AND deleted_at IS NULL AND version = #{et.version}

mapper.select:
SELECT  FROM gateway_wiki_revision
WHERE deleted_at IS NULL AND publication_status = 'PUBLISHED' AND kb_id = #{kbId}
ORDER BY create_time DESC, id DESC
LIMIT #{limit}
